CSS = '''
:root{--fondo:#F6F1EA;--sup:#FFFDF8;--tinta:#1E1A2E;--suave:#5C5870;--lin:#E6DFD3;--mor:#5B43B8;--mor2:#2A1D5C;--mor3:#140E33;--oro:#E2BF6A;--ok:#2F7A55;--mid:#8A6A1C;--high:#A33B3B}
*{box-sizing:border-box;margin:0;padding:0}
body{background:var(--fondo);color:var(--tinta);font:17px/1.6 "Instrument Sans",system-ui,sans-serif;-webkit-font-smoothing:antialiased}
a{color:var(--mor)}
.w{max-width:1120px;margin:0 auto;padding:0 20px}
header{display:none}
.tx-hero{position:relative;z-index:0;border-radius:0;background:linear-gradient(160deg,var(--mor2),var(--mor3));color:#F4F1FA;padding:34px 0 120px}
.tx-hero .w{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:36px;align-items:start}
.tx-miga{font-size:.85rem;color:#C9C2E6;margin-bottom:14px}.tx-miga a{color:#C9C2E6}
.tx-chip{display:inline-block;font-size:.8rem;font-weight:600;padding:5px 12px;border-radius:99px;background:rgba(255,255,255,.12);color:#EDE8FB;margin-bottom:14px}
h1{font:600 clamp(2rem,4.4vw,3rem)/1.1 "Bodoni Moda",serif;margin:0 0 14px;color:#fff;text-wrap:balance}
.lead{color:#D9D3EE;font-size:1.05rem;max-width:56ch}
.tx-foto{border-radius:20px;overflow:hidden;background:#241a50;box-shadow:0 30px 60px -30px rgba(0,0,0,.6)}
.tx-foto img{display:block;width:100%;height:210px;object-fit:cover}
.tx-foto div{padding:16px 18px 18px}.tx-foto b{display:block;font-size:.8rem;letter-spacing:.02em;color:#E2BF6A;margin-bottom:4px}.tx-foto p{font-size:.92rem;color:#E4DFF5}
.tx-datos{display:flex;gap:10px}.tx-datos span{flex:1;background:rgba(255,255,255,.08);border-radius:12px;padding:8px 10px;text-align:center;font-size:.78rem;color:#CFC8EA}.tx-datos span b{display:block;font:600 1.3rem "Bodoni Moda",serif;color:#fff;margin:0}
.tx-cuerpo{position:relative;z-index:1;margin-top:-90px;display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:24px;align-items:start;padding-bottom:20px}
.tx-card{background:var(--sup);border:1px solid var(--lin);border-radius:20px;box-shadow:0 20px 50px -30px rgba(20,14,51,.35)}
.tx-preg{padding:22px 24px 26px}
.prog{position:sticky;top:0;background:var(--sup);padding:12px 0 10px;z-index:5;font-size:.86rem;color:var(--suave);border-bottom:1px solid var(--lin);margin-bottom:6px}
.prog i{display:block;height:5px;background:var(--lin);border-radius:3px;margin-top:6px}.prog i b{display:block;height:100%;width:0;background:var(--mor);border-radius:3px;transition:width .2s}
.stem{font-weight:600;margin:12px 0 4px}
fieldset.q{border:0;border-bottom:1px solid var(--lin);padding:18px 0;min-width:0}fieldset.q:last-child{border-bottom:0}
.q p{margin-bottom:10px;font-weight:600;display:flex;gap:10px}.q p b{flex:none;width:26px;height:26px;border-radius:50%;background:var(--mor);color:#fff;font-size:.8rem;display:grid;place-items:center;margin-top:1px}
.ops{display:flex;flex-wrap:wrap;gap:8px;padding-left:36px}.ops label{cursor:pointer}.ops input{position:absolute;opacity:0;pointer-events:none}
.ops span{display:inline-flex;align-items:center;min-height:40px;border:1px solid #D8CFE9;border-radius:12px;padding:8px 14px;font-size:.92rem;background:#fff;transition:background .15s,border-color .15s}
.ops label:hover span{border-color:var(--mor)}
.ops input:checked+span{background:var(--mor);color:#fff;border-color:var(--mor);font-weight:600}.ops input:focus-visible+span{outline:3px solid var(--oro);outline-offset:2px}
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:46px;border:0;border-radius:99px;padding:12px 26px;background:var(--oro);color:#1b1440;font-weight:700;font-size:.98rem;font-family:inherit;cursor:pointer;margin-top:18px;text-decoration:none}
.btn.sec{background:transparent;border:1px solid currentColor;color:inherit}
#msg{display:block;margin-top:8px;color:var(--high);font-size:.9rem}
.tx-lado{position:sticky;top:16px;background:linear-gradient(170deg,var(--mor2),var(--mor3));color:#F4F1FA;border:0;padding:22px}
.tx-lado .t{font-size:.8rem;color:#C9C2E6;font-weight:600}
.tx-lado .vacio{font-size:.95rem;color:#D9D3EE;margin-top:10px}
#resultado{margin-top:6px}#resultado[hidden]{display:none}
.score{font:700 3rem/1.1 "Bodoni Moda",serif;color:#fff}.score small{font-size:1rem;color:#C9C2E6;font-weight:400}
.lvl{display:inline-block;padding:5px 12px;border-radius:99px;font-weight:700;font-size:.88rem;margin:8px 0 12px;background:#fff}.lvl.ok{color:var(--ok)}.lvl.mid{color:var(--mid)}.lvl.high{color:var(--high)}
#resultado p{color:#E4DFF5}#resultado h2{color:#fff;margin:18px 0 8px;font:600 1.1rem "Bodoni Moda",serif}
.tips{list-style:none;display:grid;gap:10px}.tips li{padding-left:12px;border-left:2px solid var(--oro);color:#E4DFF5;font-size:.94rem}.tips b{display:block;color:#fff}
.alert{margin-top:14px;padding:14px 16px;border-radius:12px;background:#FCECEC;color:#5A1D1D}.alert a{color:#8A1F1F}
#accRes .btn{margin-right:8px}
.tx-info{padding:8px 0 40px;max-width:760px}
.tx-info h2{font:600 1.5rem "Bodoni Moda",serif;margin:30px 0 10px}
.small{font-size:.88rem;color:var(--suave)}.ref{font-size:.84rem;color:var(--suave);margin-top:8px}
.tx-rejilla{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:16px;margin:0 0 40px}
.tx-test{display:flex;flex-direction:column;text-decoration:none;color:inherit;background:var(--sup);border:1px solid var(--lin);border-radius:18px;overflow:hidden;transition:border-color .2s}
.tx-test:hover{border-color:var(--mor)}.tx-test img{width:100%;height:140px;object-fit:cover;display:block}.tx-test div{padding:14px 16px 16px}
.tx-test b{font:600 1.15rem/1.25 "Bodoni Moda",serif;display:block;margin-bottom:6px}.tx-test span{font-size:.9rem;color:var(--suave)}
.tx-indice .tx-hero{padding-bottom:100px}.tx-indice .tx-cuerpo{display:block}
footer{margin-top:20px;padding:22px 0 30px;font-size:.86rem;color:var(--suave)}footer .w{max-width:1120px}
@media (max-width:900px){.tx-hero .w,.tx-cuerpo{grid-template-columns:1fr}.tx-hero{padding-bottom:70px}.tx-cuerpo{margin-top:-50px}.tx-lado{position:static}.tx-foto img{height:170px}}
@media (max-width:520px){.tx-preg{padding:16px 16px 20px}.ops{padding-left:0}.tx-datos span{font-size:.72rem}}
@media print{.tx-hero,.tx-lado .vacio,#calc,#accRes{display:none}}
'''
HEAD = '''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="aurzane-idiomas" content="no">
<script src="https://aurzane.com/aurzane-paleta.js"></script>
<title>{title}</title>
<meta name="description" content="{desc}">
<link rel="canonical" href="{url}">
{alt}
<meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{url}"><meta property="og:image" content="{og}">
<link rel="icon" href="https://aurzane.com/favicon.ico" sizes="48x48">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Bodoni+Moda:wght@600;700&family=Instrument+Sans:wght@400;600;700&display=swap" rel="stylesheet">
<script type="application/ld+json">{ld}</script>
<style>{css}</style>
</head>
<body>
<header><div class="w"><a class="logo" href="https://aurzane.com/">AUR<span>Z</span>ANE</a><nav><a href="{base}">All tests</a><a href="{es}" hreflang="es" lang="es">Español</a></nav></div></header>
'''
FOOT = '''<footer><div class="w"><p>AURZANE · Tests created and reviewed by a clinical psychologist. These questionnaires are screening tools and do not replace a professional assessment. Your answers are not sent anywhere unless you are signed in and choose to save them.</p></div></footer>
</body></html>'''

JS = r'''<script>
var CFG = %s;
(function(){
  var R = {}, $ = function(id){ return document.getElementById(id); };
  var q = '';
  CFG.items.forEach(function(t, i){
    q += '<fieldset class="q"><legend class="sr" style="position:absolute;left:-9999px">' + (i + 1) + '</legend><p><b>' + (i + 1) + '.</b>' + t + '</p><div class="ops">' +
      ((CFG.ops2items || []).indexOf(i) >= 0 ? CFG.ops2 : CFG.ops).map(function(o){ return '<label><input type="radio" name="i' + i + '" value="' + o[0] + '"><span>' + o[1] + '</span></label>'; }).join('') + '</div></fieldset>';
  });
  $('items').innerHTML = q;
  $('items').addEventListener('change', function(e){
    R[e.target.name] = +e.target.value; var n = Object.keys(R).length;
    $('cuenta').textContent = n + ' of ' + CFG.items.length + ' answered'; $('barra').style.width = (n / CFG.items.length * 100) + '%%';
  });
  $('calc').addEventListener('click', function(){
    var falta = CFG.items.findIndex(function(_, i){ return R['i' + i] === undefined; });
    if (falta >= 0) { $('msg').textContent = 'Please answer question ' + (falta + 1) + ' first.'; document.getElementsByName('i' + falta)[0].closest('.q').scrollIntoView({behavior: 'smooth', block: 'center'}); return; }
    $('msg').textContent = '';
    var total = 0; CFG.items.forEach(function(_, i){ var v = R['i' + i]; total += CFG.cortes ? (v >= CFG.cortes[i] ? 1 : 0) : (CFG.inv.indexOf(i) >= 0 ? (CFG.invBase - v) : v); });
    if (CFG.media) total = Math.round(total / CFG.items.length * 100) / 100;
    if (CFG.mult) total = total * CFG.mult;
    var nv = CFG.levels.filter(function(x){ return total >= x[0] && total <= x[1] + 0.0001; })[0] || CFG.levels[CFG.levels.length - 1];
    var shown = CFG.media ? total.toFixed(2) : total;
    var h = '<div class="score">' + shown + ' <small>out of ' + CFG.max + (CFG.cortes ? ' in the shaded zone' : '') + '</small></div><span class="lvl ' + nv[2] + '">' + nv[3] + '</span><p>' + nv[4] + '</p>';
    if (CFG.crisis != null && R['i' + CFG.crisis] > 0) h += '<div class="alert"><b>What you feel matters, and help is available now.</b> You said you have had thoughts of hurting yourself or that you would be better off dead. Please talk to someone today: in the US call or text <a href="tel:988">988</a>, in the UK and Ireland call Samaritans on <a href="tel:116123">116 123</a>, or call your local emergency number if you are in danger.</div>';
    else if (nv[2] === 'high') h += '<div class="alert"><b>Asking for help works.</b> Your doctor can refer you to psychological therapy, or you can contact a licensed psychologist directly.</div>';
    h += '<h2>What you can do</h2><ul class="tips">' + CFG.tips.map(function(t){ return '<li><b>' + t[0] + '</b>' + t[1] + '</li>'; }).join('') + '</ul>';
    $('resultado').innerHTML = h; $('resultado').hidden = false; $('accRes').hidden = false; var v = document.querySelector('.tx-lado .vacio'); if (v) v.hidden = true;
    window.__res = { titulo: CFG.titulo, valor: shown, max: CFG.max, nivel: nv[3], unidad: 'out of ' + CFG.max };
    document.body.classList.add('hecho');
    $('resultado').scrollIntoView({behavior: 'smooth', block: 'start'});
  });
})();
</script>'''


def pagina(t):
    url = BASE + t['slug'] + '/'
    cfg = {k: t.get(k) for k in ['items', 'ops', 'inv', 'min', 'max', 'levels', 'tips', 'clave']}
    cfg.update({'cortes': t.get('cortes'), 'mult': t.get('mult'), 'ops2': t.get('ops2'), 'ops2items': t.get('ops2items'), 'invBase': t.get('invBase', 0), 'media': bool(t.get('media')), 'crisis': t.get('crisis'), 'titulo': t['name']})
    cfg['clave'] = t['clave'] + '-en'
    lv = '; '.join(f"{l[0]} to {l[1]}: {l[3].lower()}" for l in t['levels'])
    faq = [(f"What is the {t['scale']}?", f"It is a validated questionnaire. Source: {t['ref']}"),
           ('How is it scored?', f"Scores range from {t['min']} to {t['max']}. {lv}."),
           ('Is this a diagnosis?', 'No. It is a screening tool. Only a qualified professional can make a diagnosis after an interview.')]
    ld = {'@context': 'https://schema.org', '@graph': [
        {'@type': 'WebApplication', 'name': t['name'], 'url': url, 'applicationCategory': 'HealthApplication', 'operatingSystem': 'Web', 'inLanguage': 'en', 'isAccessibleForFree': True,
         'offers': {'@type': 'Offer', 'price': '0', 'priceCurrency': 'EUR'}, 'publisher': {'@type': 'Organization', 'name': 'AURZANE', 'url': 'https://aurzane.com/'}},
        {'@type': 'FAQPage', 'mainEntity': [{'@type': 'Question', 'name': a, 'acceptedAnswer': {'@type': 'Answer', 'text': b}} for a, b in faq]}]}
    PT = {'anxiety-test-gad-7': 'teste-de-ansiedade-gad-7', 'depression-test-phq-9': 'teste-de-depressao-phq-9', 'wellbeing-test-who-5': 'teste-de-bem-estar-who-5'}
    alt = f'<link rel="alternate" hreflang="en" href="{url}">' + (f'<link rel="alternate" hreflang="pt-BR" href="https://mind.aurzane.com/pt/{PT[t["slug"]]}/">' if t['slug'] in PT else '') + f'<link rel="alternate" hreflang="es" href="{t["es"]}"><link rel="alternate" hreflang="x-default" href="{t["es"]}">'
    h = HEAD.format(title=E(t['name'] + ': free online questionnaire | AURZANE'), desc=E(t['desc']), url=url, alt=alt, og=t['es'] + 'og.jpg',
                    ld=json.dumps(ld, ensure_ascii=False).replace('</', '<\\/'), css=CSS, base=BASE, es=t['es'])
    mins = max(1, round(len(t['items']) * 12 / 60))
    h += f'''<main class="test">
<section class="tx-hero"><div class="w"><div>
<p class="tx-miga"><a href="{BASE}">All tests</a> / {E(t['scale'])}</p>
<span class="tx-chip">Validated questionnaire · {E(t['scale'])}</span>
<h1>{E(t['name'])}</h1>
<p class="lead">{E(t['desc'])}</p>
</div>
<div class="tx-foto"><img src="{FOTO_T(t)}" alt="" width="760" height="420"><div>
<div class="tx-datos"><span><b>{len(t['items'])}</b>questions</span><span><b>{mins}</b>min</span><span><b>Free</b>no sign-up</span></div></div></div>
</div></section>
<div class="w tx-cuerpo">
<div class="tx-card tx-preg">
<div class="prog"><span id="cuenta">0 of {len(t['items'])} answered</span><i><b id="barra"></b></i></div>
<p class="stem">{E(t['stem'])}</p>
<form id="items" onsubmit="return false"></form>
<button class="btn" id="calc" type="button">See my result</button> <span id="msg" class="small" role="alert"></span>
</div>
<aside class="tx-card tx-lado" aria-label="Your result"><p class="t">Your result</p><p class="vacio">Answer every question to see your score and what it means.</p>
<section id="resultado" hidden aria-live="polite"></section>
<div id="accRes" hidden><button class="btn" type="button" onclick="window.print()">Save as PDF</button> <a class="btn sec" href="{BASE}">Take another test</a></div>
</aside>
</div>
<div class="w tx-info">
<h2>About this test</h2>
<p>{E(t['scale'])} is a validated, widely used questionnaire. Scores range from {t['min']} to {t['max']}. {E(lv)}.</p>
<p class="ref">Reference: {E(t['ref'])}</p>
<p class="small" style="margin-top:12px">This test is for guidance only and does not replace an assessment by a health professional. ¿Prefieres hacerlo en español? <a href="{t['es']}" hreflang="es" lang="es">Versión en español</a>.</p>
</div>
</main>
'''
    h += JS % json.dumps(cfg, ensure_ascii=False) + FOOT
    return h


def indice():
    url = BASE
    ld = {'@context': 'https://schema.org', '@type': 'CollectionPage', 'name': 'Free psychological tests', 'url': url, 'inLanguage': 'en'}
    h = HEAD.format(title='Free psychological tests in English | AURZANE', desc='Validated psychological questionnaires in their original English version: personality, anxiety, depression, adult ADHD, loneliness, self-esteem, stress, burnout and more. Free and anonymous.',
                    url=url, alt=f'<link rel="alternate" hreflang="en" href="{url}"><link rel="alternate" hreflang="es" href="https://mind.aurzane.com/"><link rel="alternate" hreflang="x-default" href="https://mind.aurzane.com/">',
                    og='https://aurzane.com/og-portada.jpg', ld=json.dumps(ld), css=CSS, base=BASE, es='https://mind.aurzane.com/')
    h += ('<main class="tx-indice"><section class="tx-hero"><div class="w"><div><span class="tx-chip">MIND · English</span><h1>Free psychological tests</h1><p class="lead">Validated questionnaires in their original English wording, with an instant, clearly explained result. Created and reviewed by a clinical psychologist. Free and anonymous.</p></div></div></section>'
          '<div class="w tx-cuerpo"><div class="tx-rejilla">')
    h += (f'<a class="tx-test" href="{BASE}personality-test-big-five/"><img src="https://mind.aurzane.com/test-de-personalidad/og/test-de-personalidad.jpg" alt="" loading="lazy" width="520" height="280"><div><b>Big Five personality test</b><span>20, 50 or 120 questions · IPIP</span></div></a>')
    h += ''.join(f'<a class="tx-test" href="{BASE}{t["slug"]}/"><img src="{FOTO_T(t, 520)}" alt="" loading="lazy" width="520" height="280"><div><b>{E(t["name"])}</b><span>{len(t["items"])} questions · {E(t["scale"])}</span></div></a>' for t in TESTS)
    h += '</div><p class="small">Breathing and relaxation exercises are available in Spanish at <a href="https://mind.aurzane.com/ejercicios/" hreflang="es">mind.aurzane.com/ejercicios</a>.</p></div></main>' + FOOT
    return h


os.makedirs(OUT, exist_ok=True)
for t in TESTS:
    os.makedirs(os.path.join(OUT, t['slug']), exist_ok=True)
    open(os.path.join(OUT, t['slug'], 'index.html'), 'w', encoding='utf-8').write(pagina(t))
open(os.path.join(OUT, 'index.html'), 'w', encoding='utf-8').write(indice())
print('ok', len(TESTS))
